
.enchanter-runtime{
	/* Color — Figma variables */
	--base-white: #f2eeea;
	--base-white-50: #f2eeea80;
	--black-100: #000000;
	--black-100-50: #00000080;
	--gray-50: #8a8a8a;
	--gray-90: #1a1518;
	--ethereal-orange: #f44100;
	--module-red: #d02018;
	--interface-blue: #2e27b8;
	--payload-gold: #df9702;
	--payload-gold-text: #b87c00;
	--discount-green: #137d00;
	/* Requires / Compatible With — set `--relation-tone` from these, not a second map */
	--relation-requires: var(--module-red);
	--relation-compatible: var(--discount-green);
	--banner-information: #ff00f6;
	/* Banner Success fill from Figma Banner/Success — distinct from discount green */
	--banner-success: #21db00;
	/* Figma Line — Gray 90 (#1a1518) at 10% */
	--line: #1a15181a;

	/* Product class fills */
	--class-core: var(--black-100);
	--class-module: var(--module-red);
	--class-interface: var(--interface-blue);
	--class-payload: var(--payload-gold-text);

	/*
	 * Figma paint styles (approximate CSS; UI applies them).
	 * Named to match: Module Gradient, Interface Gradient, Base Gradient,
	 * Payload Gradient, Ethereal Gradient, and * Background Gradient.
	 *
	 * Class gradients fill FAB Press/Toggled. *-bg fills Module Color.
	 * --gradient-ethereal is Filled/FAB Default press. --gradient-expander
	 * is the named “Expander” spectrum — not the Effect strip; do not swap it.
	 */
	--gradient-module: linear-gradient(45deg, #ff0d00 0%, #f200ff 100%);
	--gradient-interface: linear-gradient(45deg, #0145cd 0%, #04815e 100%);
	--gradient-base: conic-gradient(
		#620074 2%,
		#08000f 27%,
		#000000 38%,
		#06000c 67%,
		#260046 80%
	);
	--gradient-payload: linear-gradient(45deg, #ffd900 0%, #a63d00 100%);
	/* Figma 180deg / to-bottom — first stop at the top. CSS 0deg is to-top. */
	--gradient-ethereal: linear-gradient(180deg, #f44100 0%, #d20b00 100%);
	/*
	 * Expander Effect `352:20847` — transparent at the top, Ethereal Orange at
	 * the bottom. Figma inspect: from 0.103% rgba(0,0,0,0) to 104.9% #f44100.
	 */
	--gradient-expander-effect: linear-gradient(
		180deg,
		rgb(0 0 0 / 0%) 0.1%,
		var(--ethereal-orange) 104.9%
	);
	/*
	 * Named Figma paint “Expander” — horizontal class spectrum. Not the
	 * Expander Effect strip; do not swap this in for --gradient-expander-effect.
	 */
	--gradient-expander: linear-gradient(
		90deg,
		#f44100 0%,
		#d02018 25%,
		#2e27b8 50%,
		#df9702 75%,
		#f44100 100%
	);
	--gradient-module-bg: linear-gradient(180deg, #d02018 0%, #6a100c 100%);
	--gradient-interface-bg: linear-gradient(180deg, #2e27b8 0%, #151152 100%);
	--gradient-payload-bg: linear-gradient(180deg, #df8a02 0%, #944a01 100%);
	/* Closed/Mobile Core `286:9201` — Core Gradient, #19130f → black. */
	--gradient-core-bg: linear-gradient(180deg, #19130f 0%, #000000 100%);
	/* FAB Color=Core Brown/Green Press `618:14728`. */
	--core-green: #00de1e;
	/* FAB Toggled `1156:16702` — lime → yellow, 180deg. */
	--gradient-core-fab: linear-gradient(180deg, #00de1e 0%, #ebe300 100%);


	--font-symbols: 'Noto Sans Symbols', sans-serif;
	--font-dud: 'iA Writer Duo V', 'iA Writer Duo', 'Noto Sans Symbols', sans-serif;
	--font-body: 'iA Writer Duo V', 'iA Writer Duo', 'Noto Sans Symbols', ui-monospace, monospace,
		sans-serif;
	/* Footer ASCII orb — Figma: iA Writer Mono V / Text */
	--font-mono: 'iA Writer Mono V', 'iA Writer Mono', 'Noto Sans Symbols', ui-monospace, monospace,
		sans-serif;
	--font-display: 'Bluu Next', 'Times New Roman', serif, 'Noto Sans Symbols', sans-serif;
	--text-body: 0.875rem;
	--text-header: 2.25rem;
	--text-header-mini: 1.5rem;
	--text-header-mobile: 1.75rem;
	--text-modal-title: 4.5rem;
	/* Desktop 404 Description — Figma Bluu Next Titling 29 / tracking -1% */
	--text-modal-quote: 1.8125rem;
	/* Figma letterSpacing PERCENT 15 → CSS em (15% of font-size) */
	--tracking-ascii: 0.15em;
	/*
	 * iA Writer Duo V / Mono V named instances. Figma’s style names do not
	 * map to CSS 400/700: Duo “Bold” (Body, Button Text, badges) is 500.
	 * Axes: wght 400–700, SPCG 0–150 (default 0).
	 */
	--weight-regular: 400;
	--weight-text: 450;
	--weight-body: 500;
	--weight-semibold: 525;
	/* Bluu Next Titling (`645:21298`); Bold is 700. */
	--weight-titling: 600;
	--weight-header: 700;
	--font-spcg: 0;

	/* Space / radius */
	--space-1: 4px;
	--space-2: 8px;
	--space-3: 12px;
	--space-4: 16px;
	--space-5: 24px;
	--space-6: 36px;
	--page-inset: 16px;
	/*
	 * Breakpoints — Figma artboard widths.
	 * Desktop 1440 / Tablet landscape 1194 / Tablet portrait 834 / Mobile 390.
	 * @media cannot read custom properties; keep max-width queries at token − 1px
	 * (--bp-lg → 1193px, --bp-md → 833px).
	 */
	--bp-sm: 390px;
	--bp-md: 834px;
	--bp-lg: 1194px;
	--bp-xl: 1440px;
	/* Fluid column tracks: fill the inset width at every viewport. */
	--grid-template: repeat(4, minmax(0, 1fr));
	--radius-badge: 4px;
	--radius-control: 8px;
	--control-height: 36px;
	--tap-target: 48px;
	/* Cart drawer. 300px is Figma Cart `79:3034`. Peek fallback is the mobile
	 * sheet inset; CartShell overwrites it with the live nav bottom so the
	 * sheet cannot cover EA / Cart. */
	--cart-width: 300px;
	--cart-peek: 48px;
	/*
	 * Promo badge hang — 24px sit (`262:13494`) plus Double Bundle art
	 * (`87:773` at −18px). Mast padding uses this so ETHERCRAFT / BUNDLE!
	 * clear the sticky nav. Cart does not — CART.VIEWER is a 24px system.out
	 * bar (`85:2612`) and must not inherit the 18px starburst extra.
	 * Starburst art hangs ~54px past the 144px frame; overhang is the clip
	 * budget, then pulled back so the hero track stays page-wide.
	 */
	--hero-badge-hang: calc(var(--space-5) + 18px);
	--hero-badge-overhang: 80px;

	/*
	 * Motion — quint-out for choreography and paint.
	 * Figma Hover / Focus / Pressed / Toggled are discrete skins: clip, stroke
	 * weight, and radius snap. Fill / ink / stroke *color* ease over
	 * --duration-state. CSS cubic-bezier from easings.net; JS uses the polynomials.
	 */
	--ease-quint-in: cubic-bezier(0.64, 0, 0.78, 0);
	--ease-quint-out: cubic-bezier(0.22, 1, 0.36, 1);
	--ease-quint-in-out: cubic-bezier(0.83, 0, 0.17, 1);
	--duration-state: 200ms;
	--motion-ease: var(--ease-quint-out);
	--motion: var(--duration-state) var(--motion-ease);
}

/*
 * Color tokens are registered so Hover / Focus / Pressed paints can ease.
 * Lengths (--btn-clip-h, --btn-stroke, --corner-width, …) stay typed but are
 * not transitioned — Figma skins snap those, and tweening them is what made
 * hover feel laggy. Unregistered custom properties swap at 50%.
 */
@property --btn-fill {
	syntax: '<color>';
	inherits: true;
	initial-value: transparent;
}

@property --btn-ink {
	syntax: '<color>';
	inherits: true;
	initial-value: #000000;
}

