}

@property --btn-stroke {
	syntax: '<length>';
	inherits: true;
	initial-value: 0px;
}

@property --btn-stroke-tl {
	syntax: '<length>';
	inherits: true;
	initial-value: 0px;
}

@property --btn-stroke-tr {
