/*
 * Theme mode hooks — Figma variable collection modes
 * (Static, Core, Interface, Module, Payload, Ethereal).
 *
 * --contrast is mode-dependent ink. It defaults to black on :root / Static.
 * Set `data-theme` on `html` or a subtree to override:
 *   static | core | interface | module | payload | ethereal
 */
.enchanter-runtime,.enchanter-runtime [data-theme='static']{
	--contrast: var(--black-100);
}.enchanter-runtime [data-theme='core'],.enchanter-runtime [data-theme='interface'],.enchanter-runtime [data-theme='module']{
	--contrast: var(--base-white);
}.enchanter-runtime [data-theme='payload'],.enchanter-runtime [data-theme='ethereal']{
	--contrast: var(--black-100);
}

/* < --bp-lg: tablet portrait (834) and the range below landscape */
@media (max-width: 1193px) {.enchanter-runtime{
		--grid-template: repeat(2, minmax(0, 1fr));
	}
}

/* < --bp-md: mobile. Figma Mobile inset is 8px, single column. */
@media (max-width: 833px) {.enchanter-runtime{
		--page-inset: 8px;
		--grid-template: minmax(0, 1fr);
	}
}















